"""Best five visual outputs per generation; every score and lineage retained."""
from pathlib import Path
import os
import numpy as np
from PIL import Image
import tifffile
from experiments.bora_supervised.registry import load,save
from experiments.bora_supervised.viewer import palette,overlay
from experiments.bora_group import anonymous_palette
from experiments.bora_group.viewer import expert_legend,small_mask


def publish(study,data,cycle,ranking):
    study,cycle=Path(study),Path(cycle);output=cycle/'viewer';assets=study/'viewer-assets';selected=ranking[:5]
    colours=palette(len(data.registry['ontology']['roles']));case_records=[]
    for case in data.evaluation:
        row=data.rows[case];geo=data.geo/'cases'/case;asset=assets/case;asset.mkdir(parents=True,exist_ok=True)
        original=Image.open(row['original_path']).convert('RGB');original.thumbnail((1000,850));image=np.asarray(original);size=original.size
        source=tifffile.imread(row['reference_path']);truth=np.zeros(source.shape,np.uint8)
        for k,v in row['ontology_raw_to_role'].items():truth[source==int(k)]=v
        if not (asset/'original.jpg').exists():
            original.save(asset/'original.jpg',quality=92);Image.fromarray(overlay(image,small_mask(truth,size),colours)).save(asset/'expert.jpg',quality=92)
            tiles=tifffile.imread(geo/'coarse.working.tif');groups=tifffile.imread(geo/'groups.native.tif');ac=anonymous_palette(int(tiles.max()))
            for name,mask in [('tiles',tiles),('bora',groups)]:Image.fromarray(overlay(image,small_mask(mask,size),ac)).save(asset/(name+'.jpg'),quality=92)
            Image.open(geo/'converted.png').resize(size,Image.Resampling.BILINEAR).save(asset/'converted.jpg',quality=92)
        models=[];folder=output/case;folder.mkdir(parents=True,exist_ok=True)
        for result in selected:
            entry=next(c for c in result['cases'] if c['case']==case);vector=Path(entry['vector']);mask=tifffile.imread(vector.with_name('mask.tif'))
            Image.fromarray(overlay(image,small_mask(mask,size),colours)).save(folder/(result['id']+'.jpg'),quality=92)
            models.append(dict(id=result['id'],name=result['name'],iou=entry['final']['macro_iou'],raw_iou=entry['raw']['macro_iou'],
                group_top1=entry['group']['top1'],seconds=entry['cached_deployment_seconds'],vector=os.path.relpath(vector,output),
                cleanup=entry['vector_record'].get('final_native_pixel_cleanup') or entry['vector_record']['cleanup'],boundary_segments_before=entry['vector_record']['compact_boundary_report']['before']['boundary_segments'],boundary_segments_after=entry['vector_record']['compact_boundary_report']['after']['boundary_segments']))
        case_records.append(dict(case=case,dataset=row['dataset'],split=row['split'],native_shape_yx=row['sample']['native_shape_yx'],
            native_mpp_xy=row['sample']['native_mpp_xy'],expert_legend=expert_legend(row,source),
            asset=os.path.relpath(asset,output),models=models))
    save(output/'data.json',dict(cycle=cycle.name,cases=case_records,roles=data.registry['ontology']['roles'],colours=colours.tolist(),
        mechanisms=load(cycle/'CANDIDATES.json')['candidates'],models=[{k:v for k,v in r.items() if k!='cases'} for r in selected],all_twenty=[{k:v for k,v in r.items() if k!='cases'} for r in ranking],
        selection='Adaptive validation/test reuse: development evaluation, not independent final testing',
        cohort_cases=len(data.evaluation),threshold_native_pixels=20,evaluation_policy=data.evaluation_policy,
        split_counts={s:sum(data.rows[c]['split']==s for c in data.evaluation) for s in ('validation','test')},
        dataset_counts={d:sum(data.rows[c]['dataset']==d for c in data.evaluation) for d in sorted({data.rows[c]['dataset'] for c in data.evaluation})}))
    (output/'index.html').write_text(HTML)
    completed=sorted(p.parent.name for p in (study/'cycles').glob('*/CYCLE_COMPLETE.json'))
    if cycle.name not in completed:completed.append(cycle.name)
    links=''.join(f'<li><a href="cycles/{c}/viewer/index.html">{c}: best five masks and all twenty scores</a></li>' for c in sorted(completed))
    (study/'index.html').write_text('<!doctype html><meta charset="utf-8"><title>Bora classifier evolution</title><h1>Bora tissue identity evolution</h1><p>Fixed anonymous tiling, RGB9+19, and Bora-AF. All classifiers use native fastPLS. Small regions and enclosed holes below 20 native pixels are filled before the published simplified GeoJSON export. Reused test results guide evolution; this is development evaluation.</p><ul>'+links+'</ul>')


HTML='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Bora classifier evolution</title><style>
body{font:16px system-ui;background:#f1f5f6;color:#193545;margin:20px}h1{font-size:26px}h2{font-size:20px}p{line-height:1.45}button,select{font:inherit;padding:6px}#nav{position:sticky;top:0;background:#dce8ed;padding:12px;z-index:2}.context{display:grid;grid-template-columns:repeat(3,minmax(230px,1fr));gap:12px}.methods{display:grid;grid-template-columns:repeat(5,minmax(180px,1fr));gap:10px;overflow:auto}figure{margin:0;background:white;padding:10px}img{width:100%}figcaption{font-weight:650}small{font-size:13px}table{border-collapse:collapse;background:white}td,th{padding:8px;border:1px solid #ccd5da;text-align:right}td:first-child,th:first-child{text-align:left}a{color:#00718c}.swatch{display:inline-block;width:12px;height:12px;margin:0 6px}#geo{background:white;width:100%;max-height:850px;touch-action:none}#controls{padding:12px;background:white;display:flex;gap:14px;flex-wrap:wrap}.active{outline:3px solid #007b95}@media(max-width:900px){.context,.methods{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
<h1 id="title">Bora classifier evolution</h1><p>Every algorithm uses <b>native fastPLS</b> to identify whole anonymous tissue groups. The expert-derived coarse mask, RGB9+19 conversion and Bora-AF boundaries stay fixed. Final polygon parts smaller than <b>20 native pixels of area</b> are removed and filled with adjacent tissue; isolated specks on glass are removed to background. Enclosed holes below the same threshold are filled. Both continuous polygon area and native raster counts are checked; exactly 20 is retained. Final polygons use Bora’s published converter followed by calibrated shared-boundary straight-line fitting.</p><p id="scope"></p><p><a href="../../../index.html">All completed cycles</a> · <a href="../RESULTS.json">Complete scores and selection</a> · <a href="../CANDIDATES.json">Mechanisms and parent lineage</a></p>
<details><summary>Scores for all 20 algorithms</summary><table id="score"></table></details>
<details><summary>What each algorithm does and how it evolved</summary><table id="mechanisms"></table></details><div id="nav"><button id="prev">Previous</button> <select id="dataset"></select> <select id="case"></select> <button id="next">Next</button> <span id="info"></span></div>
<h2>Original image, expert mask, input tiles, RGB conversion and Bora geometry</h2><div class="context" id="context"></div>
<h2>Best five final tissue masks, side by side</h2><div class="methods" id="methods"></div><p id="legend"></p>
<h2>Inspect the simplified GeoJSON</h2><div id="controls"><select id="method"></select><label>Opacity <input id="opacity" type="range" min="0" max="90" value="40"></label><label><input id="outlines" type="checkbox" checked>Outlines</label><button id="zoom-in">Zoom +</button><button id="zoom-out">Zoom −</button><button id="fit">Fit</button><a id="download" download>Download GeoJSON</a></div><p id="vector-info"></p><svg id="geo" xmlns="http://www.w3.org/2000/svg"></svg>
<script>
let data,shown=[],idx=0,model,box,drag,token=0;const el=x=>document.getElementById(x),ns='http://www.w3.org/2000/svg',pc=x=>x==null?'n/a':(100*x).toFixed(1)+'%',esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
fetch('data.json').then(r=>r.json()).then(d=>{data=d;model=d.models[0].id;el('title').textContent='Bora · '+d.cycle;el('scope').textContent=d.cohort_cases+' calibrated multiclass images. '+d.selection+'. Selection combines final GeoJSON IoU (50%), group balanced accuracy (30%) and group accuracy (20%), with penalties for deployment time above1 second and model complexity.';el('dataset').innerHTML='<option value="">All datasets</option>'+[...new Set(d.cases.map(c=>c.dataset))].sort().map(s=>'<option>'+s+'</option>').join('');el('score').innerHTML='<tr><th>Algorithm</th><th>Final IoU</th><th>Group accuracy</th><th>Balanced accuracy</th><th>Seconds/image</th><th>Latency penalty</th><th>Complexity penalty</th><th>Selection score</th></tr>'+d.all_twenty.map(m=>`<tr><td>${esc(m.id+' '+m.name)}</td><td>${m.mean_final_geojson_iou.toFixed(3)}</td><td>${pc(m.top1)}</td><td>${pc(m.balanced_accuracy)}</td><td>${m.mean_cached_deployment_seconds.toFixed(3)}</td><td>${m.latency_penalty.toFixed(4)}</td><td>${m.elegance_penalty.toFixed(4)}</td><td>${m.selection_score.toFixed(4)}</td></tr>`).join('');el('mechanisms').innerHTML='<tr><th>Algorithm</th><th>Mechanism</th><th>Parents</th></tr>'+d.mechanisms.map(m=>`<tr><td>${esc(m.id+' '+m.name)}</td><td>${esc(m.description)}</td><td>${esc(m.parents.join(', ')||'Initial mechanism')}</td></tr>`).join('');el('method').innerHTML=d.models.map(m=>`<option value="${m.id}">${esc(m.id+' '+m.name)}</option>`).join('');el('method').onchange=()=>{model=el('method').value;draw()};el('dataset').onchange=()=>filter();el('case').onchange=()=>select(+el('case').value);el('prev').onclick=()=>select((idx-1+shown.length)%shown.length);el('next').onclick=()=>select((idx+1)%shown.length);el('opacity').oninput=style;el('outlines').onchange=style;el('fit').onclick=fit;el('zoom-in').onclick=()=>zoom(.7);el('zoom-out').onclick=()=>zoom(1.43);filter(location.hash.slice(1))});
function filter(wanted){shown=data.cases.filter(c=>!el('dataset').value||c.dataset===el('dataset').value);el('case').innerHTML=shown.map((c,i)=>`<option value="${i}">${esc(c.case)}</option>`).join('');select(Math.max(0,shown.findIndex(c=>c.case===wanted)))}
function expertKey(c){return '<p>'+c.expert_legend.map(g=>`<span><i class="swatch" style="background:${g.role?'rgb('+data.colours[g.role]+')':'#eee'}"></i>${esc(g.source_name)}${g.scored?'':' (excluded)'}</span>`).join('<br>')+'</p><small>Unannotated and unmapped pixels do not enter quality scores.</small>'}
function select(i){idx=i;let c=shown[i];location.hash=c.case;el('case').value=i;el('info').textContent=`${i+1}/${shown.length} · ${c.split} · ${c.native_mpp_xy.join(' × ')} µm/px`;const panels=[['Original H&E','original'],['Expert tissue annotation','expert'],['Input tiles: anonymized expert-derived groups','tiles'],['Unchanged RGB9+19','converted'],['Bora-AF anonymous tissue groups','bora']];el('context').innerHTML=panels.map(([label,file])=>`<figure><figcaption>${label}</figcaption><a target="_blank" href="${c.asset}/${file}.jpg"><img src="${c.asset}/${file}.jpg"></a>${file==='expert'?expertKey(c):''}</figure>`).join('');el('methods').innerHTML=c.models.map(m=>`<figure data-model="${m.id}"><figcaption>${esc(m.id+' '+m.name)}</figcaption><p><small>Final IoU ${m.iou.toFixed(3)} · raw IoU ${m.raw_iou.toFixed(3)}<br>Group accuracy ${pc(m.group_top1)} · ${m.seconds.toFixed(3)} s/image<br>Boundary segments ${m.boundary_segments_before.toLocaleString()} → ${m.boundary_segments_after.toLocaleString()}<br>Filled ${m.cleanup.filled_regions} islands and ${m.cleanup.filled_holes} enclosed holes</small></p><a target="_blank" href="${c.case}/${m.id}.jpg"><img src="${c.case}/${m.id}.jpg"></a><button data-select="${m.id}">Inspect GeoJSON</button></figure>`).join('');document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{model=b.dataset.select;draw()});el('legend').innerHTML=data.roles.map((r,j)=>`<span><i class="swatch" style="background:rgb(${data.colours[j+1]})"></i>${esc(r.replaceAll('_',' '))}</span>`).join(' ');draw()}
async function draw(){let c=shown[idx],m=c.models.find(m=>m.id===model)||c.models[0];model=m.id;el('method').value=model;document.querySelectorAll('[data-model]').forEach(f=>f.classList.toggle('active',f.dataset.model===model));el('download').href=m.vector;const t=++token,g=await fetch(m.vector).then(r=>r.json());if(t!==token)return;const svg=el('geo');svg.replaceChildren();let image=document.createElementNS(ns,'image');image.setAttribute('href',c.asset+'/original.jpg');image.setAttribute('width',c.native_shape_yx[1]);image.setAttribute('height',c.native_shape_yx[0]);image.setAttribute('preserveAspectRatio','none');svg.append(image);for(const f of g.features){let p=document.createElementNS(ns,'path'),parts=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;p.setAttribute('d',parts.flatMap(poly=>poly.map(r=>r.map((xy,i)=>(i?'L':'M')+xy.join(',')).join(' ')+'Z')).join(' '));p.setAttribute('fill-rule','evenodd');p.setAttribute('fill',f.properties.classification.color);p.setAttribute('vector-effect','non-scaling-stroke');p.dataset.vector='true';p.onpointerenter=()=>el('vector-info').textContent=f.properties.predicted_tissue;svg.append(p)}fit();style();el('vector-info').textContent=g.features.length+' predicted tissue features · native ROI pixel coordinates · simplified shared boundaries'}
function style(){document.querySelectorAll('[data-vector]').forEach(p=>{p.setAttribute('fill-opacity',el('opacity').value/100);p.setAttribute('stroke',el('outlines').checked?'#18303b':'none');p.setAttribute('stroke-width','.7')})}
function fit(){let c=shown[idx];box=[0,0,c.native_shape_yx[1],c.native_shape_yx[0]];el('geo').style.aspectRatio=box[2]+'/'+box[3];apply()}
function apply(){el('geo').setAttribute('viewBox',box.join(' '))}function zoom(f){let w=box[2]*f,h=box[3]*f;box=[box[0]+(box[2]-w)/2,box[1]+(box[3]-h)/2,w,h];apply()}
el('geo').onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,box:box.slice()};el('geo').setPointerCapture(e.pointerId)};el('geo').onpointermove=e=>{if(!drag)return;let r=el('geo').getBoundingClientRect();box=[drag.box[0]-(e.clientX-drag.x)*drag.box[2]/r.width,drag.box[1]-(e.clientY-drag.y)*drag.box[3]/r.height,drag.box[2],drag.box[3]];apply()};el('geo').onpointerup=e=>{drag=null;el('geo').releasePointerCapture(e.pointerId)};
</script></html>'''
